def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main = core
        parts = main.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def pre_key(pre_ids):
        if pre_ids is None:
            return None
        key = []
        for ident in pre_ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    def cmp_key(v):
        major, minor, patch, pre_ids = parse(v)
        has_pre = pre_ids is not None
        return (major, minor, patch, 0 if has_pre else 1, pre_key(pre_ids) if has_pre else [])

    import functools
    def compare(a, b):
        ka = cmp_key(a)
        kb = cmp_key(b)
        # compare major,minor,patch,has_pre flag
        if ka[:4] != kb[:4]:
            return -1 if ka[:4] < kb[:4] else 1
        pa = ka[4]
        pb = kb[4]
        # compare identifiers list
        n = min(len(pa), len(pb))
        for i in range(n):
            if pa[i] != pb[i]:
                return -1 if pa[i] < pb[i] else 1
        if len(pa) != len(pb):
            return -1 if len(pa) < len(pb) else 1
        return 0

    indexed = list(enumerate(versions))
    def full_compare(x, y):
        c = compare(x[1], y[1])
        if c != 0:
            return c
        return x[0] - y[0]

    indexed.sort(key=functools.cmp_to_key(full_compare))
    return [v for i, v in indexed]

